import{_ as o,o as a,c as r,ag as t}from"./chunks/framework.B_zcDAFh.js";const f=JSON.parse('{"title":"Boing Reactor Field","description":"","frontmatter":{},"headers":[],"relativePath":"guide/boing-reactor-field.md","filePath":"guide/boing-reactor-field.md"}'),i={name:"guide/boing-reactor-field.md"};function n(s,e,l,c,d,g){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="boing-reactor-field" tabindex="-1">Boing Reactor Field <a class="header-anchor" href="#boing-reactor-field" aria-label="Permalink to &quot;Boing Reactor Field&quot;">​</a></h1><p>A <strong>Boing Reactor Field</strong> is a 3D grid of reactors that <a href="./boing-effector.html">Boing Effectors</a> push. Rather than every object owning its own reactor, the field absorbs effector influence once, and many objects then read from the field via <a href="./boing-reactor-field-sampler.html">samplers</a> or directly in shaders.</p><p>This is the right choice when you have a large number of objects (grass, props, vertices of a deforming mesh) that should all react to the same effectors across a bounded volume.</p><h2 id="inspector-at-a-glance" tabindex="-1">Inspector at a Glance <a class="header-anchor" href="#inspector-at-a-glance" aria-label="Permalink to &quot;Inspector at a Glance&quot;">​</a></h2><ul><li><strong>Hardware Mode</strong> — <code>CPU</code> for use with sampler components; <code>GPU</code> for shader-based sampling.</li><li><strong>Cell Move Mode</strong> — <code>Follow</code> (cells move with the field — visually shifting field) or <code>Wrap Around</code> (cells stay in place — visually stationary field as it moves).</li><li><strong>Cell Size</strong>, <strong>Cells X/Y/Z</strong> — grid resolution. Smaller cells = finer detail, more work.</li><li><strong>Falloff Mode / Ratio / Dimensions</strong> — how field influence tapers near the boundary (<code>None</code>, <code>Square</code>, <code>Circle</code>), and which axes the falloff applies to.</li><li><strong>Effectors</strong> — list of effectors that push this field.</li><li><strong>Params / Shared Params</strong> — spring tuning, same as on a reactor.</li></ul><h2 id="propagation" tabindex="-1">Propagation <a class="header-anchor" href="#propagation" aria-label="Permalink to &quot;Propagation&quot;">​</a></h2><p>Enabling <strong>Propagation</strong> lets disturbances spread between neighboring cells over time, producing wave-like ripples instead of strictly local pushes.</p><ul><li><strong>Position / Rotation Propagation</strong> — per-channel propagation ratio (0–1).</li><li><strong>Propagation Depth</strong> — cells per update step. Larger values propagate faster but cost more; prefer increasing cell size before depth.</li><li><strong>Anchor Propagation At Border</strong> — fix the boundary cells in place.</li></ul><p>Get comfortable with non-propagating fields first — propagation interacts subtly with cell size, depth, and spring decay.</p><p>See the <a href="/boing-kit/api/boing-reactor-field.html">API reference</a>.</p>',10)])])}const h=o(i,[["render",n]]);export{f as __pageData,h as default};
